const items = $input.all();

const records = items.map(item => {
  const cleaned = {};

  for (const [key, value] of Object.entries(item.json)) {

    // Remove row_number generated by Google Sheets
    if (key.trim().toLowerCase() === "row_number") {
      continue;
    }

    // Clean column names
    const cleanKey = key
      .trim()
      .replace(/\s+/g, "_")
      .toLowerCase();

    // Clean string values
    let cleanValue = value;

    if (typeof value === "string") {
      cleanValue = value.trim();
    }

    cleaned[cleanKey] = cleanValue;
  }

  return cleaned;
});

return [
  {
    json: {
      record_count: records.length,

      fields: records.length > 0
        ? Object.keys(records[0])
        : [],

      records: records
    }
  }
];

